<?php

declare(strict_types=1);

namespace app\service;

/** Canvas workflow releases, execution traces and manual quality appeals. */
final class ProductQualitySchema
{
    public static function statements(string $driver): array
    {
        return match ($driver) {
            'mysql' => self::mysql(),
            'pgsql' => self::pgsql(),
            default => self::sqlite(),
        };
    }

    private static function mysql(): array
    {
        return [
            "CREATE TABLE IF NOT EXISTS creative_products (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, code VARCHAR(60) NOT NULL, name VARCHAR(120) NOT NULL, description TEXT NULL, execution_mode VARCHAR(30) NOT NULL DEFAULT 'direct', current_workflow_version_id BIGINT UNSIGNED NULL, previous_workflow_version_id BIGINT UNSIGNED NULL, status VARCHAR(30) NOT NULL DEFAULT 'active', sort_order INT NOT NULL DEFAULT 0, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, PRIMARY KEY (id), UNIQUE KEY uk_creative_products_code (code), KEY idx_creative_products_status (status, sort_order, id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
            "CREATE TABLE IF NOT EXISTS workflow_template_versions (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, template_id BIGINT UNSIGNED NULL, template_code VARCHAR(80) NOT NULL, version INT NOT NULL, workflow_json LONGTEXT NOT NULL, input_map_json LONGTEXT NOT NULL, output_map_json LONGTEXT NOT NULL, dependency_manifest_json LONGTEXT NOT NULL, workflow_hash CHAR(64) NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'draft', last_test_result_json LONGTEXT NULL, created_by_admin_id BIGINT UNSIGNED NULL, published_at DATETIME NULL, created_at DATETIME NOT NULL, PRIMARY KEY (id), UNIQUE KEY uk_workflow_version (template_code, version), UNIQUE KEY uk_workflow_hash (template_code, workflow_hash), KEY idx_workflow_version_status (template_code, status, id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
            "CREATE TABLE IF NOT EXISTS workflow_release_events (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, product_code VARCHAR(60) NOT NULL, workflow_version_id BIGINT UNSIGNED NULL, previous_workflow_version_id BIGINT UNSIGNED NULL, event_type VARCHAR(30) NOT NULL, reason TEXT NULL, created_by_admin_id BIGINT UNSIGNED NULL, created_at DATETIME NOT NULL, PRIMARY KEY (id), KEY idx_workflow_release_events_product (product_code, id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
            "CREATE TABLE IF NOT EXISTS generation_execution_attempts (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, generation_item_id BIGINT UNSIGNED NOT NULL, attempt_no INT NOT NULL, execution_channel VARCHAR(30) NOT NULL, capability VARCHAR(60) NOT NULL, logical_model VARCHAR(190) NULL, sub2api_model_alias VARCHAR(190) NULL, model_adapter_code VARCHAR(80) NULL, model_adapter_version INT NULL, model_adapter_hash CHAR(64) NULL, workflow_code VARCHAR(80) NULL, workflow_version INT NULL, workflow_hash CHAR(64) NULL, client_request_id VARCHAR(190) NULL, comfyui_prompt_id VARCHAR(190) NULL, sub2api_request_id VARCHAR(190) NULL, provider_task_id VARCHAR(190) NULL, idempotency_key VARCHAR(190) NOT NULL, status VARCHAR(30) NOT NULL, duration_ms INT NULL, usage_summary_json LONGTEXT NOT NULL, request_summary_json LONGTEXT NOT NULL, result_summary_json LONGTEXT NOT NULL, error_code VARCHAR(80) NULL, error_message TEXT NULL, failed_node VARCHAR(190) NULL, started_at DATETIME NOT NULL, completed_at DATETIME NULL, created_at DATETIME NOT NULL, PRIMARY KEY (id), UNIQUE KEY uk_generation_attempt (generation_item_id, attempt_no), UNIQUE KEY uk_generation_attempt_idempotency (idempotency_key), KEY idx_generation_attempt_status (status, created_at), KEY idx_generation_attempt_requests (comfyui_prompt_id, sub2api_request_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
            "CREATE TABLE IF NOT EXISTS generation_quality_appeals (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, appeal_no VARCHAR(60) NOT NULL, merchant_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, job_id BIGINT UNSIGNED NOT NULL, job_item_id BIGINT UNSIGNED NOT NULL, asset_id BIGINT UNSIGNED NOT NULL, product_code VARCHAR(60) NOT NULL, issue_type VARCHAR(60) NOT NULL, description TEXT NULL, status VARCHAR(30) NOT NULL DEFAULT 'pending', charged_credits INT NULL, consume_ledger_id BIGINT UNSIGNED NULL, refund_ledger_id BIGINT UNSIGNED NULL, active_item_key VARCHAR(100) NULL, refunded_item_key VARCHAR(100) NULL, evidence_snapshot_json LONGTEXT NOT NULL, admin_reason TEXT NULL, user_visible_reply TEXT NULL, reviewed_by_admin_id BIGINT UNSIGNED NULL, submitted_at DATETIME NOT NULL, review_started_at DATETIME NULL, resolved_at DATETIME NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, PRIMARY KEY (id), UNIQUE KEY uk_quality_appeal_no (appeal_no), UNIQUE KEY uk_quality_appeal_active (active_item_key), UNIQUE KEY uk_quality_appeal_refunded (refunded_item_key), KEY idx_quality_appeal_admin (status, submitted_at, id), KEY idx_quality_appeal_merchant (merchant_id, id), KEY idx_quality_appeal_item (job_item_id, id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
            "CREATE TABLE IF NOT EXISTS generation_quality_appeal_events (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, appeal_id BIGINT UNSIGNED NOT NULL, event_type VARCHAR(40) NOT NULL, actor_type VARCHAR(30) NOT NULL, actor_id BIGINT UNSIGNED NULL, message TEXT NULL, metadata_json LONGTEXT NOT NULL, created_at DATETIME NOT NULL, PRIMARY KEY (id), KEY idx_quality_appeal_events (appeal_id, id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
            "CREATE TABLE IF NOT EXISTS quality_improvement_items (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, product_code VARCHAR(60) NOT NULL, dimension_type VARCHAR(40) NOT NULL, dimension_value VARCHAR(190) NOT NULL, issue_type VARCHAR(60) NOT NULL, sample_count INT NOT NULL DEFAULT 0, approved_count INT NOT NULL DEFAULT 0, issue_rate DECIMAL(8,4) NOT NULL DEFAULT 0, status VARCHAR(30) NOT NULL DEFAULT 'open', source_appeal_ids_json LONGTEXT NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, PRIMARY KEY (id), UNIQUE KEY uk_quality_improvement_dimension (product_code, dimension_type, dimension_value, issue_type), KEY idx_quality_improvement_status (status, updated_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
        ];
    }

    private static function pgsql(): array
    {
        return [
            "CREATE TABLE IF NOT EXISTS creative_products (id BIGSERIAL PRIMARY KEY, code VARCHAR(60) NOT NULL UNIQUE, name VARCHAR(120) NOT NULL, description TEXT NULL, execution_mode VARCHAR(30) NOT NULL DEFAULT 'direct', current_workflow_version_id BIGINT NULL, previous_workflow_version_id BIGINT NULL, status VARCHAR(30) NOT NULL DEFAULT 'active', sort_order INTEGER NOT NULL DEFAULT 0, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL)",
            "CREATE INDEX IF NOT EXISTS idx_creative_products_status ON creative_products(status, sort_order, id)",
            "CREATE TABLE IF NOT EXISTS workflow_template_versions (id BIGSERIAL PRIMARY KEY, template_id BIGINT NULL, template_code VARCHAR(80) NOT NULL, version INTEGER NOT NULL, workflow_json TEXT NOT NULL, input_map_json TEXT NOT NULL DEFAULT '{}', output_map_json TEXT NOT NULL DEFAULT '{}', dependency_manifest_json TEXT NOT NULL DEFAULT '[]', workflow_hash CHAR(64) NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'draft', last_test_result_json TEXT NULL, created_by_admin_id BIGINT NULL, published_at TIMESTAMP NULL, created_at TIMESTAMP NOT NULL, UNIQUE (template_code, version), UNIQUE (template_code, workflow_hash))",
            "CREATE INDEX IF NOT EXISTS idx_workflow_version_status ON workflow_template_versions(template_code, status, id)",
            "CREATE TABLE IF NOT EXISTS workflow_release_events (id BIGSERIAL PRIMARY KEY, product_code VARCHAR(60) NOT NULL, workflow_version_id BIGINT NULL, previous_workflow_version_id BIGINT NULL, event_type VARCHAR(30) NOT NULL, reason TEXT NULL, created_by_admin_id BIGINT NULL, created_at TIMESTAMP NOT NULL)",
            "CREATE INDEX IF NOT EXISTS idx_workflow_release_events_product ON workflow_release_events(product_code, id)",
            "CREATE TABLE IF NOT EXISTS generation_execution_attempts (id BIGSERIAL PRIMARY KEY, generation_item_id BIGINT NOT NULL, attempt_no INTEGER NOT NULL, execution_channel VARCHAR(30) NOT NULL, capability VARCHAR(60) NOT NULL, logical_model VARCHAR(190) NULL, sub2api_model_alias VARCHAR(190) NULL, model_adapter_code VARCHAR(80) NULL, model_adapter_version INTEGER NULL, model_adapter_hash CHAR(64) NULL, workflow_code VARCHAR(80) NULL, workflow_version INTEGER NULL, workflow_hash CHAR(64) NULL, client_request_id VARCHAR(190) NULL, comfyui_prompt_id VARCHAR(190) NULL, sub2api_request_id VARCHAR(190) NULL, provider_task_id VARCHAR(190) NULL, idempotency_key VARCHAR(190) NOT NULL UNIQUE, status VARCHAR(30) NOT NULL, duration_ms INTEGER NULL, usage_summary_json TEXT NOT NULL DEFAULT '{}', request_summary_json TEXT NOT NULL DEFAULT '{}', result_summary_json TEXT NOT NULL DEFAULT '{}', error_code VARCHAR(80) NULL, error_message TEXT NULL, failed_node VARCHAR(190) NULL, started_at TIMESTAMP NOT NULL, completed_at TIMESTAMP NULL, created_at TIMESTAMP NOT NULL, UNIQUE (generation_item_id, attempt_no))",
            "CREATE INDEX IF NOT EXISTS idx_generation_attempt_status ON generation_execution_attempts(status, created_at)",
            "CREATE INDEX IF NOT EXISTS idx_generation_attempt_requests ON generation_execution_attempts(comfyui_prompt_id, sub2api_request_id)",
            "CREATE TABLE IF NOT EXISTS generation_quality_appeals (id BIGSERIAL PRIMARY KEY, appeal_no VARCHAR(60) NOT NULL UNIQUE, merchant_id BIGINT NOT NULL, user_id BIGINT NOT NULL, job_id BIGINT NOT NULL, job_item_id BIGINT NOT NULL, asset_id BIGINT NOT NULL, product_code VARCHAR(60) NOT NULL, issue_type VARCHAR(60) NOT NULL, description TEXT NULL, status VARCHAR(30) NOT NULL DEFAULT 'pending', charged_credits INTEGER NULL, consume_ledger_id BIGINT NULL, refund_ledger_id BIGINT NULL, active_item_key VARCHAR(100) NULL UNIQUE, refunded_item_key VARCHAR(100) NULL UNIQUE, evidence_snapshot_json TEXT NOT NULL DEFAULT '{}', admin_reason TEXT NULL, user_visible_reply TEXT NULL, reviewed_by_admin_id BIGINT NULL, submitted_at TIMESTAMP NOT NULL, review_started_at TIMESTAMP NULL, resolved_at TIMESTAMP NULL, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL)",
            "CREATE INDEX IF NOT EXISTS idx_quality_appeal_admin ON generation_quality_appeals(status, submitted_at, id)",
            "CREATE INDEX IF NOT EXISTS idx_quality_appeal_merchant ON generation_quality_appeals(merchant_id, id)",
            "CREATE INDEX IF NOT EXISTS idx_quality_appeal_item ON generation_quality_appeals(job_item_id, id)",
            "CREATE TABLE IF NOT EXISTS generation_quality_appeal_events (id BIGSERIAL PRIMARY KEY, appeal_id BIGINT NOT NULL, event_type VARCHAR(40) NOT NULL, actor_type VARCHAR(30) NOT NULL, actor_id BIGINT NULL, message TEXT NULL, metadata_json TEXT NOT NULL DEFAULT '{}', created_at TIMESTAMP NOT NULL)",
            "CREATE INDEX IF NOT EXISTS idx_quality_appeal_events ON generation_quality_appeal_events(appeal_id, id)",
            "CREATE TABLE IF NOT EXISTS quality_improvement_items (id BIGSERIAL PRIMARY KEY, product_code VARCHAR(60) NOT NULL, dimension_type VARCHAR(40) NOT NULL, dimension_value VARCHAR(190) NOT NULL, issue_type VARCHAR(60) NOT NULL, sample_count INTEGER NOT NULL DEFAULT 0, approved_count INTEGER NOT NULL DEFAULT 0, issue_rate NUMERIC(8,4) NOT NULL DEFAULT 0, status VARCHAR(30) NOT NULL DEFAULT 'open', source_appeal_ids_json TEXT NOT NULL DEFAULT '[]', created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, UNIQUE (product_code, dimension_type, dimension_value, issue_type))",
            "CREATE INDEX IF NOT EXISTS idx_quality_improvement_status ON quality_improvement_items(status, updated_at)",
        ];
    }

    private static function sqlite(): array
    {
        return [
            "CREATE TABLE IF NOT EXISTS creative_products (id INTEGER PRIMARY KEY AUTOINCREMENT, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, description TEXT NULL, execution_mode TEXT NOT NULL DEFAULT 'direct', current_workflow_version_id INTEGER NULL, previous_workflow_version_id INTEGER NULL, status TEXT NOT NULL DEFAULT 'active', sort_order INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL)",
            "CREATE INDEX IF NOT EXISTS idx_creative_products_status ON creative_products(status, sort_order, id)",
            "CREATE TABLE IF NOT EXISTS workflow_template_versions (id INTEGER PRIMARY KEY AUTOINCREMENT, template_id INTEGER NULL, template_code TEXT NOT NULL, version INTEGER NOT NULL, workflow_json TEXT NOT NULL, input_map_json TEXT NOT NULL DEFAULT '{}', output_map_json TEXT NOT NULL DEFAULT '{}', dependency_manifest_json TEXT NOT NULL DEFAULT '[]', workflow_hash TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'draft', last_test_result_json TEXT NULL, created_by_admin_id INTEGER NULL, published_at TEXT NULL, created_at TEXT NOT NULL, UNIQUE (template_code, version), UNIQUE (template_code, workflow_hash))",
            "CREATE INDEX IF NOT EXISTS idx_workflow_version_status ON workflow_template_versions(template_code, status, id)",
            "CREATE TABLE IF NOT EXISTS workflow_release_events (id INTEGER PRIMARY KEY AUTOINCREMENT, product_code TEXT NOT NULL, workflow_version_id INTEGER NULL, previous_workflow_version_id INTEGER NULL, event_type TEXT NOT NULL, reason TEXT NULL, created_by_admin_id INTEGER NULL, created_at TEXT NOT NULL)",
            "CREATE INDEX IF NOT EXISTS idx_workflow_release_events_product ON workflow_release_events(product_code, id)",
            "CREATE TABLE IF NOT EXISTS generation_execution_attempts (id INTEGER PRIMARY KEY AUTOINCREMENT, generation_item_id INTEGER NOT NULL, attempt_no INTEGER NOT NULL, execution_channel TEXT NOT NULL, capability TEXT NOT NULL, logical_model TEXT NULL, sub2api_model_alias TEXT NULL, model_adapter_code TEXT NULL, model_adapter_version INTEGER NULL, model_adapter_hash TEXT NULL, workflow_code TEXT NULL, workflow_version INTEGER NULL, workflow_hash TEXT NULL, client_request_id TEXT NULL, comfyui_prompt_id TEXT NULL, sub2api_request_id TEXT NULL, provider_task_id TEXT NULL, idempotency_key TEXT NOT NULL UNIQUE, status TEXT NOT NULL, duration_ms INTEGER NULL, usage_summary_json TEXT NOT NULL DEFAULT '{}', request_summary_json TEXT NOT NULL DEFAULT '{}', result_summary_json TEXT NOT NULL DEFAULT '{}', error_code TEXT NULL, error_message TEXT NULL, failed_node TEXT NULL, started_at TEXT NOT NULL, completed_at TEXT NULL, created_at TEXT NOT NULL, UNIQUE (generation_item_id, attempt_no))",
            "CREATE INDEX IF NOT EXISTS idx_generation_attempt_status ON generation_execution_attempts(status, created_at)",
            "CREATE INDEX IF NOT EXISTS idx_generation_attempt_requests ON generation_execution_attempts(comfyui_prompt_id, sub2api_request_id)",
            "CREATE TABLE IF NOT EXISTS generation_quality_appeals (id INTEGER PRIMARY KEY AUTOINCREMENT, appeal_no TEXT NOT NULL UNIQUE, merchant_id INTEGER NOT NULL, user_id INTEGER NOT NULL, job_id INTEGER NOT NULL, job_item_id INTEGER NOT NULL, asset_id INTEGER NOT NULL, product_code TEXT NOT NULL, issue_type TEXT NOT NULL, description TEXT NULL, status TEXT NOT NULL DEFAULT 'pending', charged_credits INTEGER NULL, consume_ledger_id INTEGER NULL, refund_ledger_id INTEGER NULL, active_item_key TEXT NULL UNIQUE, refunded_item_key TEXT NULL UNIQUE, evidence_snapshot_json TEXT NOT NULL DEFAULT '{}', admin_reason TEXT NULL, user_visible_reply TEXT NULL, reviewed_by_admin_id INTEGER NULL, submitted_at TEXT NOT NULL, review_started_at TEXT NULL, resolved_at TEXT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL)",
            "CREATE INDEX IF NOT EXISTS idx_quality_appeal_admin ON generation_quality_appeals(status, submitted_at, id)",
            "CREATE INDEX IF NOT EXISTS idx_quality_appeal_merchant ON generation_quality_appeals(merchant_id, id)",
            "CREATE INDEX IF NOT EXISTS idx_quality_appeal_item ON generation_quality_appeals(job_item_id, id)",
            "CREATE TABLE IF NOT EXISTS generation_quality_appeal_events (id INTEGER PRIMARY KEY AUTOINCREMENT, appeal_id INTEGER NOT NULL, event_type TEXT NOT NULL, actor_type TEXT NOT NULL, actor_id INTEGER NULL, message TEXT NULL, metadata_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL)",
            "CREATE INDEX IF NOT EXISTS idx_quality_appeal_events ON generation_quality_appeal_events(appeal_id, id)",
            "CREATE TABLE IF NOT EXISTS quality_improvement_items (id INTEGER PRIMARY KEY AUTOINCREMENT, product_code TEXT NOT NULL, dimension_type TEXT NOT NULL, dimension_value TEXT NOT NULL, issue_type TEXT NOT NULL, sample_count INTEGER NOT NULL DEFAULT 0, approved_count INTEGER NOT NULL DEFAULT 0, issue_rate NUMERIC NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'open', source_appeal_ids_json TEXT NOT NULL DEFAULT '[]', created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE (product_code, dimension_type, dimension_value, issue_type))",
            "CREATE INDEX IF NOT EXISTS idx_quality_improvement_status ON quality_improvement_items(status, updated_at)",
        ];
    }
}
